  </Theme>
</HudDocument>";

        /// <summary>Deserialize + <see cref="HudDocument.Sanitize"/> one embedded constant, name
        /// stamped to <paramref name="name"/>. Returns null (never throws) if the embed somehow
        /// fails to parse — the caller then falls back further (the generic starter), exactly
        /// like <see cref="Glassy40Default"/>'s own failure path.</summary>
        private static HudDocument Build(string xml, string name)
        {
            try
            {
                var ser = new System.Xml.Serialization.XmlSerializer(typeof(HudDocument));
                using (var r = new System.IO.StringReader(xml))
                {
                    var doc = (HudDocument)ser.Deserialize(r);
                    if (doc != null && doc.Elements != null && doc.Elements.Count > 0)
                    {
                        doc.Sanitize();
                        doc.Name = name;
                        return doc;
                    }
                }
            }
            catch (System.Exception e)
            {
                Core.UIALog.Warn("ShippedProfiles: '" + name + "' embed failed to parse: " + e.Message);
            }
            return null;
        }

        public static HudDocument BuildStationeersBlue() => Build(StationeersBlueXml, StationeersBlueName);
        public static HudDocument BuildPureHud() => Build(PureHudXml, PureHudName);
        public static HudDocument BuildStationeersBlueMinimalist() => Build(StationeersBlueMinimalistXml, StationeersBlueMinimalistName);
        public static HudDocument BuildZirillianRed() => Build(ZirillianRedXml, ZirillianRedName);
    }
}
